options(monitora.qfield.somente_funcoes=TRUE);source('qfield/monitora_criar_qfield.R',encoding='UTF-8');suppressPackageStartupMessages(library(sf))
n<-0;ok<-function(name,v){stopifnot(isTRUE(v));n<<-n+1;cat('PASS',name,'\n')};fails<-function(x)inherits(try(force(x),silent=TRUE),'try-error')
r<-tempfile();dir.create(r);cr<-31983
poly<-function(x1,y1,x2,y2)st_polygon(list(matrix(c(x1,y1,x2,y1,x2,y2,x1,y2,x1,y1),ncol=2,byrow=TRUE)))
ae<-st_sf(geometry=st_sfc(poly(499000,7999000,502000,8001000),crs=cr))
g<-st_as_sf(data.frame(PA=paste0('PA',1:5),chave_grade=letters[1:5],id_grade=1:5,categoria='grade',x=500000+c(0,100,200,300,400),y=8000000),coords=c('x','y'),crs=cr)
road<-st_sf(geometry=st_sfc(st_linestring(matrix(c(500000,7999000,500000,8001000),ncol=2,byrow=TRUE)),crs=cr))
layer<-list(x=road,papel='estradas_pavimentadas',nome='vias_pav',fonte='fixture');c<-mq_protocol(MQ_CONFIG);c$estratificar_vegetacao<-FALSE
src<-mq_road_sources(list(layer),c,r);z<-mq_road_screen(g,src,ae,c,r)
ok('distancia_segmento_limiar_exato',!z$mq_viavel_vias[1]&&all(z$mq_viavel_vias[-1]))
ok('direcao_alternativa',grepl('N',z$mq_direcoes_vias[2])&&!grepl('O',z$mq_direcoes_vias[2]))
ok('ids_geometria_preservados',identical(st_geometry(g),st_geometry(z))&&identical(g$chave_grade,z$chave_grade))
c$prioritarios<-list(n=NULL,percentual=20);c$alternativos<-list(n=NULL,percentual=NULL);sel<-mq_select(z,c);ok('denominador_original_selecao_simples',sum(sel$categoria=='prioritario')==1&&sum(sel$categoria=='alternativo')==2&&sel$categoria[1]=='grade')
c2<-c;c2$politica_insuficiencia<-'bloquear';c2$prioritarios<-list(n=2,percentual=NULL);ok('insuficiencia_sem_reducao',fails(mq_select(z,c2)))
old<-z;old$categoria[1]<-'prioritario';ok('historico_conflitante_bloqueado',fails(mq_select(old,c)))
z$mq_apto<-TRUE;z$mq_formacao<-'campestre';c3<-c;c3$estratificar_vegetacao<-TRUE;d<-mq_design_select(z,c3,r);ok('restricao_no_solver',sum(d$categoria!='grade')==3&&d$categoria[1]=='grade')
cf<-c;cf$usar_estradas_pavimentadas<-FALSE;ok('desabilitar_exibe_sem_filtrar',length(mq_road_sources(list(layer),cf,r))==0)
ct<-c;ct$usar_estradas_pavimentadas<-TRUE;ok('exigida_ausente_bloqueia',fails(mq_road_sources(list(),ct,r)))
empty<-layer;empty$x<-road[FALSE,];ok('exigida_vazia_bloqueia',fails(mq_road_sources(list(empty),ct,r)))
ok('auto_ausente_nao_comprova_ausencia',length(mq_road_sources(list(),c,r))==0)
wide<-layer;wide$x$largura_m<-20;zw<-mq_road_screen(g,mq_road_sources(list(wide),c,r),ae,c,r);ok('largura_descontada_do_eixo',!zw$mq_viavel_vias[2]&&zw$mq_viavel_vias[3])
wide$x$largura_m<--1;ok('largura_invalida_bloqueia',fails(mq_road_sources(list(wide),c,r)))
for(role in c('estradas_terra','trilhas_preexistentes')) {
 l<-layer;l$papel<-role;gap<-c$distancias_viarias_m[[role]];p<-g[1,];st_geometry(p)<-st_sfc(st_point(c(500000+gap,8000000)),crs=cr)
 zz<-mq_road_screen(p,mq_road_sources(list(l),c,r),ae,c,r);ok(paste0(role,'_limiar_exato'),zz$mq_viavel_vias)
 st_geometry(p)<-st_sfc(st_point(c(500000+gap-.1,8000000)),crs=cr);zz<-mq_road_screen(p,mq_road_sources(list(l),c,r),ae,c,r);ok(paste0(role,'_inferior_bloqueia'),!zz$mq_viavel_vias)
}
ci<-MQ_CONFIG;ci$perfil<-'ilha';ok('ilha_padrao_piloto',mq_protocol(ci)$transecto_m==25&&all(mq_protocol(ci)$grade_m==30));ci$parametros_protocolo<-list(transecto_m=25,grade_m=c(30,30));ci<-mq_protocol(ci);mq_validate_config(ci)
ok('ilha_nao_herda_regras',length(ci$direcoes_campo)==0&&length(ci$distancias_viarias_m)==0&&is.na(ci$distancia_min_m)&&ci$transecto_m==25)
ok('ilha_vias_so_visuais',length(mq_road_sources(list(layer),ci,r))==0)
mq_diagnostics(g,list(layer),ae,ci,r);ok('ilha_sem_diagnostico_campestre',file.exists(file.path(r,'procedimento_campo_nao_aplicado.txt'))&&!file.exists(file.path(r,'simulacoes_direcoes.csv')))
cp<-ci;cp$perfil<-'personalizado';ok('personalizado_exige_regras',fails(mq_protocol(cp)));cp$parametros_protocolo$direcoes<-'N';cp$parametros_protocolo$distancias_viarias_m<-c(estradas_pavimentadas=20);cp<-mq_protocol(cp);ok('personalizado_expresso',identical(cp$direcoes_campo,'N')&&cp$distancias_viarias_m[[1]]==20)
# Leitura recursiva; nomes internos/arquivo inequívocos e nome curto em campo.
inp<-tempfile();dir.create(file.path(inp,'vias'),recursive=TRUE);st_write(ae,file.path(inp,'areas_elegiveis.gpkg'),quiet=TRUE);st_write(road,file.path(inp,'vias/estradas_pavimentadas.gpkg'),layer='estradas_pavimentadas',quiet=TRUE);scratch<-tempfile();dir.create(scratch);read<-mq_read(inp,scratch);ok('nome_padronizado_recursivo',any(vapply(read$camadas,function(l)l$papel=='estradas_pavimentadas'&&l$nome=='vias_pav',logical(1))))
legacy<-layer;legacy$papel<-'rodovias';ok('rodovia_nao_implica_pavimento',length(mq_road_sources(list(legacy),c,r))==0)
# Via fora das AEs ainda restringe ponto situado perto da borda.
small<-st_sf(geometry=st_sfc(poly(500010,7999900,500100,8000100),crs=cr));ext<-g[1,];st_geometry(ext)<-st_geometry(ext)+c(20,0);st_crs(ext)<-cr;ok('via_externa_AE',!mq_road_screen(ext,src,small,c,r)$mq_viavel_vias)
ok('PA_vazio_preservado',nrow(mq_road_screen(g[FALSE,],src,ae,c,r))==0)
tiny<-st_sf(geometry=st_sfc(poly(500195,7999995,500205,8000005),crs=cr));ok('via_distante_nao_introduz_restricao_AE',mq_road_screen(g[3,],src,tiny,c,r)$mq_viavel_vias)
footprint<-layer;footprint$x<-st_sf(geometry=st_sfc(poly(499990,7999900,500010,8000100),crs=cr))
ok('via_poligono_distancia_borda',!mq_road_screen(g[2,],mq_road_sources(list(footprint),c,r),ae,c,r)$mq_viavel_vias)
zold<-z;zold$categoria[1]<-'prioritario';ok('historico_conflitante_solver',fails(mq_design_select(zold,c3,r)))
cat('TOTAL',n,'PASS\n')
